mapper.select:
select
    coalesce(sum(total_tokens), 0) as totalTokens,
    coalesce(sum(input_tokens), 0) as inputTokens,
    coalesce(sum(output_tokens), 0) as outputTokens,
    case
        when coalesce(sum(total_tokens), 0) = 0 then 0.0
        else coalesce(sum(input_tokens), 0) * 1.0 / coalesce(sum(total_tokens), 0)
    end as inputTokenRatio,
    case
        when coalesce(sum(total_tokens), 0) = 0 then 0.0
        else coalesce(sum(output_tokens), 0) * 1.0 / coalesce(sum(total_tokens), 0)
    end as outputTokenRatio,
    count(*) as totalCalls,
    coalesce(sum(case when status = 'SUCCESS' then 1 else 0 end), 0) as successCalls,
    coalesce(sum(case when status = 'FAILED' then 1 else 0 end), 0) as failedCalls,
    case
        when count(*) = 0 then 0.0
        else sum(case when status = 'SUCCESS' then 1 else 0 end) * 1.0 / count(*)
    end as successRate,
    avg(case when status = 'SUCCESS' then duration_millis else null end) as averageDurationMillis
from llm_log
where created_at >= #{startTime}
  and created_at < #{endTime}
